import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    t = int(data[idx])
    idx += 1
    results = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1
        if n == 0:
            results.append(-1)
            continue

        arr = list(map(int, data[idx:idx+n]))
        idx += n

        inversions = []
        for i in range(n - 1):
            if arr[i] > arr[i + 1]:
                inversions.append((i, i + 1))

        if len(inversions) == 0:
            results.append(-1)
        elif len(inversions) > 1:
            results.append(-1)
        else:
            pos = inversions[0][0]
            candidates = []

            if pos - 1 >= 0:
                test_arr = arr.copy()
                test_arr[pos - 1], test_arr[pos] = test_arr[pos], test_arr[pos - 1]
                valid = True
                for i in range(len(test_arr) - 1):
                    if test_arr[i] > test_arr[i + 1]:
                        valid = False
                        break
                if valid:
                    candidates.append(pos - 1)

            test_arr2 = arr.copy()
            test_arr2[pos], test_arr2[pos + 1] = test_arr2[pos + 1], test_arr2[pos]
            valid2 = True
            for i in range(len(test_arr2) - 1):
                if test_arr2[i] > test_arr2[i + 1]:
                    valid2 = False
                    break
            if valid2:
                candidates.append(pos)

            if len(candidates) == 1:
                results.append(candidates[0])
            else:
                results.append(-1)

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
